def verify(witness):
    # Pure function: exact integer arithmetic, no imports, no I/O, no floats.
    # Recompute every quantity from the witness; fail closed on any mismatch.
    lb_num = witness['lower_bound_check']
    ub_num = witness['upper_bound_check']
    if lb_num != '5^24181 <= 7^20000':
        return False
    if ub_num != '7^50000 <= 5^60453':
        return False
    ok1 = pow(5, 24181) <= pow(7, 20000)      # lower bound: 5^0.20905 <= 7/5
    ok2 = pow(7, 50000) <= pow(5, 60453)      # upper bound: 7/5 <= 5^0.20906
    return bool(ok1 and ok2)

RESULT = verify(WITNESS)
